# Generated by secure-by-design v0.1.0 for DPDP §8(7) (Retention).
# Maps to: ISO 27001 A.8.10 (Information Deletion).
# Reads from ../../privacy-security-manifest.yaml.
# Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
# Docs: docs/scaffolds/retention_runner.md
#
# Runs daily (or on-demand). For each dataCategory in the manifest, finds
# records past their retentionDays and either erases or anonymizes them.

from __future__ import annotations

from collections.abc import Awaitable, Callable, Sequence
from dataclasses import asdict, dataclass
from datetime import datetime, timezone
from typing import Literal, Protocol

from ..security.audit_log import audit_log


@dataclass(frozen=True)
class RetentionRule:
    category: str              # matches manifest.dataCategories[].name
    retention_days: int
    table: str                 # your table / collection / model name
    timestamp_field: str       # the column that anchors retention (created_at, last_accessed_at, consent expiry)
    strategy: Literal['hard-delete', 'anonymize', 'soft-delete-then-purge']
    # 'soft-delete-then-purge' marks deleted=true at retention_days, hard-deletes after legal_hold_days.
    legal_hold_days: int | None = None


@dataclass(frozen=True)
class RetentionResult:
    inspected: int
    erased: int
    anonymized: int
    soft_deleted: int
    skipped_legal_hold: int


class RetentionAdapter(Protocol):
    async def apply(self, rule: RetentionRule, now: datetime) -> RetentionResult:
        """
        Apply the rule. Implementation talks to your ORM / database.
        Must return counts so the runner can emit a structured audit event.
        """
        ...


_adapter: RetentionAdapter | None = None


def set_retention_adapter(adapter: RetentionAdapter) -> None:
    global _adapter
    _adapter = adapter


async def run_retention(rules: Sequence[RetentionRule], when: datetime | None = None) -> None:
    if _adapter is None:
        raise RuntimeError('secure-by-design: RetentionAdapter not configured.')
    now = when or datetime.now(timezone.utc)

    for rule in rules:
        try:
            result = await _adapter.apply(rule, now)
            await audit_log.event(
                'retention.run',
                actor='system:retention-runner',
                target=rule.category,
                attrs={
                    'table': rule.table,
                    'strategy': rule.strategy,
                    'retention_days': rule.retention_days,
                    **asdict(result),
                },
            )
        except Exception as e:
            await audit_log.event(
                'retention.run',
                actor='system:retention-runner',
                target=rule.category,
                severity='ERROR',
                outcome='failure',
                attrs={'error': str(e) or type(e).__name__},
            )
            # Continue — one rule failing should not stop the others.


def daily_retention_task(rules: Sequence[RetentionRule]) -> Callable[[], Awaitable[None]]:
    """Helper to schedule daily runs. Wire to your job runner (cron, Celery beat, Temporal)."""

    async def task() -> None:
        await run_retention(rules)

    return task
